# SPSC リングバッファ（割り込みセーフ）

## 設計方針

| 項目 | 方針 |
|---|---|
| 生産者 | ISR（割り込みハンドラ） |
| 消費者 | メインループ |
| 容量 | 常に 2 のべき乗（マスク演算で剰余を回避） |
| 満杯判定 | 常に 1 スロット空ける（`head == tail` は空、`head == tail+1` は満） |
| 同期 | ロック不要。`__atomic` 組み込みでメモリ順序を保証 |

---

## 1. ヘッダ — `spsc_ring.h`

```c
#ifndef SPSC_RING_H
#define SPSC_RING_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* capacity は必ず 2 のべき乗（コンパイル時チェックは static_assert で） */
#define SPSC_CAPACITY  256u   /* 例: 256 バイト */
static_assert((SPSC_CAPACITY & (SPSC_CAPACITY - 1)) == 0,
              "SPSC_CAPACITY must be a power of 2");

typedef struct {
    volatile uint32_t head;          /* 生産者 (ISR) が更新 */
    volatile uint32_t tail;          /* 消費者 (main) が更新 */
    volatile uint8_t  data[SPSC_CAPACITY];
} spsc_ring_t;

/* ---- API ---- */
void spsc_ring_init(spsc_ring_t *ring);

/* 生産者側（ISR から呼ぶ） */
bool spsc_ring_push(spsc_ring_t *ring, uint8_t byte);

/* 消費者側（メインループから呼ぶ） */
bool spsc_ring_pop(spsc_ring_t *ring, uint8_t *out);

/* 補助 */
uint32_t spsc_ring_available(const spsc_ring_t *ring);  /* 読み出し可能バイト数 */
uint32_t spsc_ring_free(const spsc_ring_t *ring);       /* 書き込み可能バイト数 */

#endif /* SPSC_RING_H */
```

## 2. ソース — `spsc_ring.c`

```c
#include "spsc_ring.h"

/* 2 のべき乗マスク */
#define MASK(x)  ((x) & (SPSC_CAPACITY - 1))

/* ------------------------------------------------------------------ */
void spsc_ring_init(spsc_ring_t *ring)
{
    ring->head = 0;
    ring->tail = 0;
    for (uint32_t i = 0; i < SPSC_CAPACITY; i++)
        ring->data[i] = 0;
}

/* ------------------------------------------------------------------ */
/*  生産者（ISR）                                                     */
bool spsc_ring_push(spsc_ring_t *ring, uint8_t byte)
{
    uint32_t h = __atomic_load_n(&ring->head, __ATOMIC_RELAXED);
    uint32_t t = __atomic_load_n(&ring->tail, __ATOMIC_ACQUIRE);

    /* 1 スロット空けることで full/empty を区別 */
    if (MASK(h + 1) == t)
        return false;           /* バッファ満杯 */

    /* ---- 書き込み（単一スレッドなのでアトミック不要） ---- */
    ring->data[MASK(h)] = byte;

    /* データがメモリに届いてから head を進める */
    __atomic_store_n(&ring->head, h + 1, __ATOMIC_RELEASE);
    return true;
}

/* ------------------------------------------------------------------ */
/*  消費者（メインループ）                                            */
bool spsc_ring_pop(spsc_ring_t *ring, uint8_t *out)
{
    uint32_t t = __atomic_load_n(&ring->tail, __ATOMIC_RELAXED);
    uint32_t h = __atomic_load_n(&ring->head, __ATOMIC_ACQUIRE);

    if (t == h)
        return false;           /* 空 */

    *out = ring->data[MASK(t)];

    /* 読み出し完了後に tail を進める */
    __atomic_store_n(&ring->tail, t + 1, __ATOMIC_RELEASE);
    return true;
}

/* ------------------------------------------------------------------ */
uint32_t spsc_ring_available(const spsc_ring_t *ring)
{
    uint32_t h = __atomic_load_n(&ring->head, __ATOMIC_ACQUIRE);
    uint32_t t = __atomic_load_n(&ring->tail, __ATOMIC_ACQUIRE);
    return MASK(h - t);
}

uint32_t spsc_ring_free(const spsc_ring_t *ring)
{
    return SPSC_CAPACITY - 1u - spsc_ring_available(ring);
}
```

