```c
#ifndef SPSC_RING_H
#define SPSC_RING_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* 容量はコンパイル時定数（2のべき乗）。例: 256 */
#ifndef SPSC_RING_CAPACITY
#define SPSC_RING_CAPACITY  256U
#endif

/* キャパシティが2のべき乗であることをコンパイル時に保証 */
_Static_assert((SPSC_RING_CAPACITY & (SPSC_RING_CAPACITY - 1)) == 0,
               "SPSC_RING_CAPACITY must be a power of 2");

typedef struct {
    volatile uint32_t head;   /* プロデューサが更新（書き込み位置） */
    uint32_t          _pad1[15]; /* キャッシュライン分離 (64B/ライン) */

    volatile uint32_t tail;   /* コンシューマが更新（読み取り位置） */
    uint32_t          _pad2[15];

    volatile uint8_t  buf[SPSC_RING_CAPACITY];
} spsc_ring_t;

/* ---- API ---- */

/** バッファを初期化（ゼロクリア） */
void spsc_ring_init(spsc_ring_t *ring);

/** 1 バイト書き込み（ISR から呼ぶ想定）。成功 true / 満杯 false */
bool spsc_ring_push(spsc_ring_t *ring, uint8_t byte);

/** 1 バイト読み取り。成功 true / 空 false */
bool spsc_ring_pop(spsc_ring_t *ring, uint8_t *byte);

/** 現在の要素数（参考。正確には head - tail の差分） */
uint32_t spsc_ring_count(const spsc_ring_t *ring);

/** 空判定 */
static inline bool spsc_ring_empty(const spsc_ring_t *ring)
{
    return ring->head == ring->tail;
}

/** 満杯判定 */
static inline bool spsc_ring_full(const spsc_ring_t *ring)
{
    return (ring->head - ring->tail) == SPSC_RING_CAPACITY;
}

#endif /* SPSC_RING_H */
```

