## `spsc_ring.c`

```c
#include "spsc_ring.h"

/* ------------------------------------------------------------------ */
/*  メモリバリア (x86: mfence / ARM: dmb)                               */
/*  GCC/Clang: __atomic_thread_fence                                  */
/* ------------------------------------------------------------------ */
#if defined(__GNUC__) || defined(__clang__)
  #define RING_BARRIER() __atomic_thread_fence(__ATOMIC_ACQ_REL)
#else
  #define RING_BARRIER() __asm__ volatile("" ::: "memory")
#endif

/* ------------------------------------------------------------------ */
void spsc_ring_init(spsc_ring_t *ring)
{
    ring->head = 0;
    ring->tail = 0;
    for (uint32_t i = 0; i < SPSC_RING_CAPACITY; i++)
        ring->buf[i] = 0;
}

/* ------------------------------------------------------------------ */
bool spsc_ring_push(spsc_ring_t *ring, uint8_t byte)
{
    uint32_t head = ring->head;
    uint32_t tail = ring->tail;

    /* 満杯チェック: 1バイト余裕を残す (full == capacity-1 条件) */
    if ((head - tail) == SPSC_RING_CAPACITY) {
        return false;   /* 満杯 */
    }

    ring->buf[head & (SPSC_RING_CAPACITY - 1)] = byte;

    /* ★ このバリアが重要: バッファ書き込み → head 更新 の順序を保証 */
    RING_BARRIER();
    ring->head = head + 1;

    return true;
}

/* ------------------------------------------------------------------ */
bool spsc_ring_pop(spsc_ring_t *ring, uint8_t *byte)
{
    uint32_t tail = ring->tail;
    uint32_t head = ring->head;

    if (tail == head) {
        return false;   /* 空 */
    }

    *byte = ring->buf[tail & (SPSC_RING_CAPACITY - 1)];

    /* ★ バッファ読み取り → tail 更新 の順序を保証 */
    RING_BARRIER();
    ring->tail = tail + 1;

    return true;
}

/* ------------------------------------------------------------------ */
uint32_t spsc_ring_count(const spsc_ring_t *ring)
{
    return ring->head - ring->tail;   /* 無符号減算でラップaround 吸収 */
}
